<script setup>
import PaymentStatusBadge from './PaymentStatusBadge.vue'
import {getPaymentMethodLabel,paymentAmount} from '../../utils/paymentStatus'
import {formatDateTime} from '../../utils/formatters'
defineProps({payment:{type:Object,required:true},staff:Boolean})
</script>
<template><div class="payment-summary"><PaymentStatusBadge :status="payment.status"/><dl class="order-facts"><dt>طريقة الدفع</dt><dd>{{ getPaymentMethodLabel(payment.method) }}</dd><template v-if="payment.amount!=null"><dt>مبلغ هذه المحاولة</dt><dd>{{ paymentAmount(payment.amount,payment.currency) }}</dd></template><template v-if="staff"><dt>مزود الدفع</dt><dd>{{ payment.provider||'دفع عند الاستلام' }}</dd></template><template v-if="payment.created_at"><dt>وقت الإنشاء</dt><dd>{{ formatDateTime(payment.created_at) }}</dd></template><template v-if="payment.paid_at"><dt>وقت التحصيل</dt><dd>{{ formatDateTime(payment.paid_at) }}</dd></template><template v-if="payment.failed_at"><dt>وقت تعذر الدفع</dt><dd>{{ formatDateTime(payment.failed_at) }}</dd></template><template v-if="payment.cancelled_at"><dt>وقت الإلغاء</dt><dd>{{ formatDateTime(payment.cancelled_at) }}</dd></template><template v-if="payment.refunded_amount!=null"><dt>المبلغ المسترد المسجل</dt><dd>{{ paymentAmount(payment.refunded_amount,payment.currency) }}</dd></template></dl><p v-if="['cash','network'].includes(payment.method)&&payment.status==='pending'">بانتظار تحصيل الدفع لدى المطعم. إنشاء الطلب أو اكتماله لا يعني تحصيل المبلغ.</p><p v-if="payment.status==='processing'">لم تتأكد نتيجة الدفع بعد. تابع الحالة من المطعم؛ لا تفترض فشل العملية.</p><p v-if="payment.status==='failed'">تعذرت هذه المحاولة. حالة الطلب وحالة محاولات الدفع الأخرى تعرض بشكل منفصل.</p></div></template>
<style scoped>.payment-summary{min-width:0}.payment-summary dd{overflow-wrap:anywhere}.payment-summary p{margin-block:8px}</style>
